// The shape of the roadmap files and the small helpers that need no React.
// This file has no server imports besides zod, so `node --test` can load it.
//
//   src/data/roadmap-lessons.json  generated by scripts/build-roadmap.mjs
//   src/data/roadmap-phases.json   written by hand: stages, summaries, links to the 14 Parts

import { z } from "zod";
import type { Lang } from "./i18n.ts";

/** The lesson pages live on the curriculum site, one per lesson folder. */
export const LESSON_BASE_URL = "https://aiengineeringfromscratch.com/lesson?path=phases/";

/** The curriculum the roadmap follows. */
export const CURRICULUM_URL = "https://github.com/rohitg00/ai-engineering-from-scratch";

export const LessonSchema = z.strictObject({
  n: z.number().int().positive(),
  title: z.string().min(1),
  dir: z.string().regex(/^\d\d-[a-z0-9-]+$/),
  minutes: z.number().int().positive(),
});

export const LessonsFileSchema = z.strictObject({
  phases: z.array(
    z.strictObject({
      phase: z.number().int().min(0),
      folder: z.string().regex(/^\d\d-[a-z0-9-]+$/),
      title: z.string().min(1),
      hours: z.number().int().positive(),
      lessons: z.array(LessonSchema).min(1),
    }),
  ),
});

const Localized = z.strictObject({ title: z.string().min(1), summary: z.string().min(1) });

export const PhasesFileSchema = z.strictObject({
  stages: z.array(
    z.strictObject({
      id: z.string().regex(/^[a-z-]+$/),
      phases: z.array(z.number().int().min(0)).min(1),
      title: z.string().min(1),
      summary: z.string().min(1),
      bn: Localized,
    }),
  ),
  phases: z.array(
    z.strictObject({
      phase: z.number().int().min(0),
      /** Part of the suggested path for an applied AI engineer; false means optional depth. */
      core: z.boolean(),
      /** Slugs of the site's 14 Parts that cover the same ground. */
      topics: z.array(z.string()),
      summary: z.string().min(1),
      bn: z.string().min(1),
    }),
  ),
});

export type Lesson = z.infer<typeof LessonSchema>;
export type Phase = {
  phase: number;
  folder: string;
  title: string;
  /** The hours the curriculum states for the phase. */
  hours: number;
  /** The sum of the lesson estimates, in minutes. */
  minutes: number;
  core: boolean;
  topics: string[];
  summary: string;
  bnSummary: string;
  lessons: Lesson[];
};
export type Stage = {
  id: string;
  title: string;
  summary: string;
  bn: { title: string; summary: string };
  phases: Phase[];
};

/** The progress key of a lesson: "<phase>/<lesson number>". */
export function lessonKey(phase: number, n: number): string {
  return `${phase}/${n}`;
}

export function lessonUrl(phase: Pick<Phase, "folder">, lesson: Pick<Lesson, "dir">): string {
  return `${LESSON_BASE_URL}${phase.folder}/${lesson.dir}`;
}

/** The page of a lesson on this site. */
export function lessonPath(phase: Pick<Phase, "folder">, lesson: Pick<Lesson, "dir">): string {
  return `/roadmap/${phase.folder}/${lesson.dir}/`;
}

/** Joins the two files. Throws on a gap, a repeat, or a stage that skips a phase. */
export function buildRoadmap(lessonsFile: unknown, phasesFile: unknown): Stage[] {
  const lessons = LessonsFileSchema.parse(lessonsFile);
  const meta = PhasesFileSchema.parse(phasesFile);

  const phases = new Map<number, Phase>();
  for (const p of lessons.phases) {
    const info = meta.phases.find((m) => m.phase === p.phase);
    if (!info) throw new Error(`roadmap-phases.json has no entry for phase ${p.phase}`);
    if (phases.has(p.phase)) throw new Error(`Phase ${p.phase} is listed twice in roadmap-lessons.json`);
    const seen = new Set<number>();
    for (const lesson of p.lessons) {
      if (seen.has(lesson.n)) throw new Error(`Phase ${p.phase} has two lessons numbered ${lesson.n}`);
      seen.add(lesson.n);
    }
    phases.set(p.phase, {
      phase: p.phase,
      folder: p.folder,
      title: p.title,
      hours: p.hours,
      minutes: p.lessons.reduce((sum, lesson) => sum + lesson.minutes, 0),
      core: info.core,
      topics: info.topics,
      summary: info.summary,
      bnSummary: info.bn,
      lessons: p.lessons,
    });
  }
  const extra = meta.phases.filter((m) => !phases.has(m.phase));
  if (extra.length) throw new Error(`roadmap-phases.json has no lessons for phase ${extra[0].phase}`);

  const staged = new Set<number>();
  const stages = meta.stages.map((stage): Stage => ({
    id: stage.id,
    title: stage.title,
    summary: stage.summary,
    bn: stage.bn,
    phases: stage.phases.map((n) => {
      const phase = phases.get(n);
      if (!phase) throw new Error(`Stage "${stage.id}" names phase ${n}, which does not exist`);
      if (staged.has(n)) throw new Error(`Phase ${n} is in two stages`);
      staged.add(n);
      return phase;
    }),
  }));
  const loose = [...phases.keys()].filter((n) => !staged.has(n));
  if (loose.length) throw new Error(`Phase ${loose[0]} is in no stage`);
  return stages;
}

/** A lesson length: "45 min" under two hours, "3.5 h" above. `fmt` writes the number in the digits of `lang`. */
export function formatDuration(minutes: number, lang: Lang, fmt: (n: number) => string): string {
  if (minutes < 120) return lang === "bn" ? `${fmt(minutes)} মিনিট` : `${fmt(minutes)} min`;
  const hours = Math.round((minutes / 60) * 10) / 10;
  return lang === "bn" ? `${fmt(hours)} ঘণ্টা` : `${fmt(hours)} h`;
}
